int zero_init {};   // Value init to 0
int x {10};
double d {1.23};

// List init prevents narrowing conversions (Error)
// int fails_narrow {1.9};

struct Point { int x, y; };
Point p {5, 10};
int arr[3] {1, 2};  // arr[2] is 0 (zero-initialized)

// Class with explicit constructor OK
class Config {
public:
    explicit Config(int size) {}
};
Config c {10};

// std::vector<T> (Initializer List ctor)
vector<int> v {10, 20, 30};

// std::array<T, N> (aggregate init)
array<float, 2> a {1.0f, 2.0f};

// C++20 Designated Initializers
struct Data { int id; float val; };
Data d1 {.val = 5.5f, .id = 99};
